const r = await tools.pwsh({
  description: "Extract nowcoder neitui and lw text",
  command: `cd "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts"
foreach($f in @("_b_nc_neitui.html","_b_nc_lw.html")){
  Write-Host "=== $f ==="
  $t = Get-Content $f -Raw -Encoding UTF8
  [regex]::Matches($t,'<title>([\\s\\S]*?)</title>') | %{ $_.Groups[1].Value }
  $p = [regex]::Replace($t,'<script[\\s\\S]*?</script>','')
  $p = [regex]::Replace($p,'<[^>]+>',' ')
  $p = [regex]::Replace($p,'\\s+',' ')
  $idx = $p.IndexOf('默认 最新')
  if($idx -lt 0){ $idx = [Math]::Min(1200,$p.Length) }
  $p.Substring($idx,[Math]::Min(2000,$p.Length-$idx))
  Write-Host ""
}`,
  timeoutMs: 60000
});
console.log(r.kind === "foreground" ? r.stdout.text : JSON.stringify(r));
